.root {
  --card-surface: var(--color-card, #fff);
  --card-ink: var(--color-foreground, #111);
  --card-secondary: var(--color-muted-foreground, #666);
  --card-line: var(--color-border, #e5e5e5);
  --card-canvas: var(--color-muted, #f5f5f5);
  --card-backing: var(--color-muted, #f5f5f5);
  --card-padding: 24px;
  --card-silhouette: polygon(0 0, calc(100% - 84px) 0, calc(100% - 68px) 16px, 100% 16px, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%);
  position: relative;
  isolation: isolate;
  min-width: 0;
  height: 100%;
  padding: 0 8px 8px 0;
  color: var(--card-ink);
}

.root[data-variant="inverse"] {
  --card-surface: var(--color-foreground, #111);
  --card-ink: var(--color-background, #fff);
  --card-secondary: color-mix(in srgb, var(--card-ink) 65%, transparent);
  --card-line: color-mix(in srgb, var(--card-ink) 22%, var(--card-surface));
  --card-canvas: color-mix(in srgb, var(--card-ink) 6%, var(--card-surface));
  --card-backing: color-mix(in srgb, var(--card-ink) 12%, var(--card-surface));
}

.root[data-size="compact"] {
  --card-padding: 18px;
}

.root::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 6px 2px 2px 6px;
  clip-path: var(--card-silhouette);
  background: repeating-linear-gradient(135deg, var(--card-line) 0 1px, var(--card-backing) 1px 5px);
  transition: transform 280ms cubic-bezier(.2, .8, .2, 1);
}

.face {
  position: relative;
  isolation: isolate;
  display: flex;
  min-width: 0;
  height: 100%;
  flex-direction: column;
  transition: transform 280ms cubic-bezier(.2, .8, .2, 1);
}

.face::before,
.face::after {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
  clip-path: var(--card-silhouette);
}

.face::before {
  inset: 0;
  background: var(--card-line);
  transition: background-color 240ms ease;
}

.face::after {
  inset: 1px;
  background: var(--card-surface);
}

.header {
  display: flex;
  min-width: 0;
  min-height: 64px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 24px var(--card-padding) 18px;
}

.identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
}

.icon {
  display: inline-flex;
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--card-line);
}

.icon > svg { width: 15px; height: 15px; }

.eyebrow,
.badge {
  font-family: var(--font-mono-mono, ui-monospace, monospace);
  font-size: 9px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.eyebrow { color: var(--card-secondary); overflow-wrap: anywhere; }
.badge { flex-shrink: 0; max-width: 46%; padding: 4px 7px; border: 1px solid var(--card-line); overflow-wrap: anywhere; }

.preview,
.imageFrame {
  position: relative;
  min-width: 0;
  margin: 0 var(--card-padding);
  border: 1px solid var(--card-line);
  background: var(--card-canvas);
}

.preview {
  display: grid;
  min-height: 176px;
  align-content: center;
  justify-items: center;
  padding: 24px 18px;
}

.preview::before,
.preview::after {
  content: "";
  position: absolute;
  width: 7px;
  height: 7px;
  border-color: var(--card-ink);
  opacity: .35;
  pointer-events: none;
}
.preview::before { top: 7px; left: 7px; border-top: 1px solid; border-left: 1px solid; }
.preview::after { right: 7px; bottom: 7px; border-right: 1px solid; border-bottom: 1px solid; }
.preview > * { min-width: 0; max-width: 100%; }
.face > :is(.preview, .imageFrame):first-child { margin-top: 32px; }
.imageFrame { overflow: hidden; }
.image { display: block; width: 100%; height: auto; aspect-ratio: 16 / 10; object-fit: cover; transition: transform 400ms cubic-bezier(.2, .8, .2, 1); }

.body { flex: 1; min-width: 0; padding: 5px var(--card-padding) 24px; }
.withoutHeader { padding-top: 32px; }
.afterMedia { margin-top: 22px; padding-top: 22px; border-top: 1px dashed var(--card-line); }
.title { margin: 0; color: var(--card-ink); font-size: 25px; font-weight: 600; letter-spacing: -.04em; line-height: 1.17; overflow-wrap: anywhere; }
.description { margin-top: 10px; color: var(--card-secondary); font-size: 13px; line-height: 1.75; overflow-wrap: anywhere; }
.content { min-width: 0; margin-top: 18px; }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 22px; }
.footer { min-width: 0; border-top: 1px solid var(--card-line); padding: 16px var(--card-padding) 20px; }
.corner { position: absolute; right: 9px; bottom: 8px; width: 6px; height: 6px; border-top: 1px solid var(--card-ink); border-left: 1px solid var(--card-ink); opacity: .3; transform: rotate(45deg); }
.root :focus-visible { outline: 2px solid var(--card-ink); outline-offset: 4px; }
.root:focus-within > .face::before { background: var(--card-ink); }
.root[data-size="compact"] .preview { min-height: 132px; padding: 18px 14px; }
.root[data-size="compact"] .title { font-size: 21px; }
.root[data-size="compact"] .header { min-height: 58px; padding-top: 22px; padding-bottom: 14px; }
.root[data-size="compact"] .body { padding-bottom: 18px; }
.root[data-size="compact"] .afterMedia { margin-top: 18px; padding-top: 18px; }

@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .root:hover > .face { transform: translateY(-4px); }
  .root:hover::before { transform: translate(2px, 2px); }
  .root:hover > .face::before { background: var(--card-ink); }
  .root:hover > .face > .imageFrame > .image { transform: scale(1.025); }
}

@media (prefers-reduced-motion: no-preference) {
  .root:focus-within > .face { transform: translateY(-4px); }
  .root:focus-within::before { transform: translate(2px, 2px); }
}

@media (max-width: 400px) {
  .root { --card-padding: 18px; }
  .header { gap: 8px; }
  .eyebrow { font-size: 8px; }
  .title { font-size: 22px; }
  .preview { padding-right: 14px; padding-left: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .root::before, .face, .face::before, .image { transition: none; }
}

